const norm=v=>String(v??'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().replace(/\s+/g,' ').trim();
const base=v=>norm(v).replace(/\s*-\s*plancha$/,'');
const cache=new WeakMap();
function ficha(p){if(cache.has(p))return cache.get(p);const f=familiaDe(p), c=norm(p.codigo||p.referencia), n=base(p.nombre), d=base(p.descripcion), formato=norm(p.formato)||(/-\s*plancha$/i.test(p.nombre||'')?'plancha':'');let best=-1, matches=[];
for(const r of filas){if(r[1]!==f)continue;if(formato&&norm(r[6])!==formato)continue;let score=0;const rc=norm(r[3]),rn=base(r[4]),rd=base(r[5]);if(c&&rc===c&&!['embalaje','materia prima aux.'].includes(c))score+=100;if(d&&rd===d)score+=50;if(n&&(n===rn||n===rd))score+=40;if(norm(p.material)&&norm(p.material)===norm(r[7]))score+=2;if(score<40)continue;if(score>best){best=score;matches=[r]}else if(score===best)matches.push(r)}
let r=matches.length===1?matches[0]:matches.find(x=>Number(p.excelFila)===x[0]);const proveedor=norm(p.proveedor||p.ubicacion);let rank=r?r[0]:Infinity; if(!r&&proveedor){const group=filas.filter(x=>x[1]===f&&norm(x[2])===proveedor);if(group.length)rank=group[group.length-1][0]+0.5;}const out={rank,proveedor:r?r[2]:(p.proveedor||p.ubicacion||''),matched:!!r};cache.set(p,out);return out;}
export function proveedorOrden(p){return ficha(p).proveedor;}
const alfabeto=new Intl.Collator("es",{numeric:true,sensitivity:"base"});
const nombreMaterial=p=>String(p.nombre||p.descripcion||p.material||"").trim();
export function compararOrden(a,b){const fa=FAMILIAS.indexOf(familiaDe(a)),fb=FAMILIAS.indexOf(familiaDe(b));const x=ficha(a),y=ficha(b);if(fa===fb&&(fa===1||fa===2)){return alfabeto.compare(nombreMaterial(a),nombreMaterial(b))||alfabeto.compare(proveedorOrden(a),proveedorOrden(b))||alfabeto.compare(String(a.codigo||""),String(b.codigo||""))||String(a.id||"").localeCompare(String(b.id||""));}return (fa<0?99:fa)-(fb<0?99:fb)||(x.rank===y.rank?0:x.rank-y.rank)||norm(x.proveedor).localeCompare(norm(y.proveedor),'es')||norm(a.nombre).localeCompare(norm(b.nombre),'es',{numeric:true})||norm(a.codigo).localeCompare(norm(b.codigo),'es',{numeric:true})||String(a.id||'').localeCompare(String(b.id||''));}
